ations"}, {"id": "d48a6f81-d308-464e-bf2d-2513ea48a3d1", "type": "concept", "title": "Exercise is Medicine framework"}, {"id": "544698e5-0c1c-4884-8b7b-40d8c651d145", "type": "concept", "title": "Evidence hierarchy"}, {"id": "30d2ae89-4587-4477-9b92-75f6a4ba260e", "type": "concept", "title": "Standard operating procedures"}]}, {"id": "ff59665c-193f-4a29-96d9-797443e69ca4", "type": "subtopic", "title": "Client-centered prescription", "description": "Prescription begins with the client's goals, context, barriers, and readiness.", "children": [{"id": "223bcaec-2e9f-40b1-8e0e-ab3ed5273d42", "type": "concept", "title": "Shared decision-making"}, {"id": "f48aab81-b94f-490c-8f6b-d8ba1c7bad3e", "type": "concept", "title": "SMART goals"}, {"id": "6ac32de7-938f-4fa6-ac57-bb01b0743d56", "type": "concept", "title": "Cultural humility"}, {"id": "ba6a0552-01ec-441b-94c7-91305e301e07", "type": "concept", "title": "Motivational interviewing basics"}, {"id": "27633f78-9378-4a1c-ab30-25fedfbdde55", "type": "concept", "title": "Adherence planning"}]}]}, {"id": "381a018c-2204-4550-93f2-fba9d99829fc", "type": "topic", "title": "Health Screening and Preparticipation Evaluation", "description": "Use health history, questionnaires, signs and symptoms, medication review, and referral criteria to determine readiness for exercise testing and training.", "children": [{"id": "fae3f1f3-74a1-4c85-a94f-d25f42d9cecb", "type": "subtopic", "title": "Health history and questionnaires", "description": "Students learn to collect information that changes test selection, safety, and referral decisions.", "children": [{"id": "e1ab81b0-1bd7-49b9-b79a-65b8e8d1fd73", "type": "concept", "title": "PAR-Q+ concepts"}, {"id": "3aee2755-33fe-4ebb-be97-6f5c8dc35aaf", "type": "concept", "title": "Medical history"}, {"id": "fe7d09ab-c3ba-4230-8c53-899a9327fe89", "type": "concept", "title": "Exercise history"}, {"id": "304ef93b-38a1-48f1-8527-c8d239b00e19", "type": "concept", "title": "Medication review"}, {"id": "886f